    52→template <class TableTupleType, rfl::internal::StringLiteral _name,
    53→          rfl::internal::StringLiteral _alias>
    54→struct MakeField<TableTupleType, Col<_name, _alias>> {
    55→  static_assert(all_columns_exist<TableTupleType, Col<_name, _alias>>(),
    56→                "A required column does not exist.");
    57→
    58→  static constexpr bool is_aggregation = false;
    59→  static constexpr bool is_column = true;
    60→  static constexpr bool is_operation = false;
    61→
    62→  using TableType =
    63→      get_table_t<typename Col<_name, _alias>::Alias, TableTupleType>;
    64→
    65→  using Name = Literal<_name>;
    66→  using Type = rfl::field_type_t<_name, TableType>;
    67→
    68→  dynamic::SelectFrom::Field operator()(const auto&) const {
    69→    return dynamic::SelectFrom::Field{dynamic::Operation{
    70→        .val = dynamic::Column{.alias = to_alias<Literal<_alias>>(),
    71→                               .name = _name.str()}}};
    72→  }
    73→};
