    75→template <class TableTupleType, class T>
    76→struct MakeField<TableTupleType, Value<T>> {
    77→  static constexpr bool is_aggregation = false;
    78→  static constexpr bool is_column = false;
    79→  static constexpr bool is_operation = false;
    80→
    81→  using Name = Nothing;
    82→  using Type = std::remove_cvref_t<T>;
    83→
    84→  dynamic::SelectFrom::Field operator()(const auto& _val) const {
