    90→template <class TableTupleType, class ValueType,
    91→          rfl::internal::StringLiteral _new_name>
    92→struct MakeField<TableTupleType, As<ValueType, _new_name>> {
    93→  static constexpr bool is_aggregation =
    94→      MakeField<TableTupleType, ValueType>::is_aggregation;
    95→  static constexpr bool is_column =
    96→      MakeField<TableTupleType, ValueType>::is_column;
    97→  static constexpr bool is_operation =
    98→      MakeField<TableTupleType, ValueType>::is_operation;
    99→
   100→  using Name = Literal<_new_name>;
   101→  using Type =
   102→      typename MakeField<TableTupleType, std::remove_cvref_t<ValueType>>::Type;
   103→
   104→  dynamic::SelectFrom::Field operator()(const auto& _as) const {
   105→    return dynamic::SelectFrom::Field{
   106→        .val =
   107→            dynamic::Operation{
   108→                .val =
   109→                    MakeField<TableTupleType, std::remove_cvref_t<ValueType>>{}(
   110→                        _as.val)
   111→                        .val.val},
   112→        .as = _new_name.str()};
   113→  }
   114→};
