   116→template <class TableTupleType, AggregationOp _agg, class ValueType>
   117→struct MakeField<TableTupleType, Aggregation<_agg, ValueType>> {
   118→  static_assert(
   119→      std::is_integral_v<
   120→          remove_nullable_t<underlying_t<TableTupleType, ValueType>>> ||
   121→          std::is_floating_point_v<
   122→              remove_nullable_t<underlying_t<TableTupleType, ValueType>>>,
   123→      "Values inside the aggregation must be numerical.");
   124→
   125→  // Recursively checks if a type contains any aggregations.
   126→  template <class T>
   127→  struct HasAggregations;
   128→
   129→  // Case: No operation.
   130→  template <class T>
   131→    requires(!MakeField<TableTupleType, remove_as_t<T>>::is_operation)
   132→  struct HasAggregations<T> {
   133→    static constexpr bool value =
   134→        MakeField<TableTupleType, remove_as_t<T>>::is_aggregation;
   135→  };
   136→
   137→  // Case: Is operations: Check all operands.
   138→  template <class T>
   139→    requires(MakeField<TableTupleType, remove_as_t<T>>::is_operation)
   140→  struct HasAggregations<T> {
   141→    static constexpr bool value = HasAggregations<
   142→        typename MakeField<TableTupleType, remove_as_t<T>>::Operands>::value;
   143→  };
   144→
   145→  // Case: Is a set of operands from an operation..
   146→  template <class... FieldTypes>
   147→  struct HasAggregations<rfl::Tuple<FieldTypes...>> {
   148→    static constexpr bool value =
   149→        (false || ... || HasAggregations<FieldTypes>::value);
   150→  };
   151→
   152→  static_assert(!HasAggregations<remove_as_t<ValueType>>::value,
   153→                "Nested aggregations are not allowed. Please restructure your "
   154→                "query to avoid nested aggregations.");
   155→
   156→  static constexpr bool is_aggregation = true;
   157→  static constexpr bool is_column = false;
   158→  static constexpr bool is_operation = false;
   159→
   160→  using Name = Nothing;
   161→  using Type =
   162→      typename MakeField<TableTupleType, std::remove_cvref_t<ValueType>>::Type;
   163→
   164→  dynamic::SelectFrom::Field operator()(const auto& _val) const {
   165→    using DynamicAggregationType = dynamic_aggregation_t<_agg>;
   166→    return dynamic::SelectFrom::Field{dynamic::Operation{
   167→        .val = dynamic::Aggregation{DynamicAggregationType{
   168→            .val = Ref<dynamic::Operation>::make(
   169→                MakeField<TableTupleType, std::remove_cvref_t<ValueType>>{}(
   170→                    _val.val)
   171→                    .val)}}}};
   172→  }
   173→};
