   301→  using Operands = rfl::Tuple<Operand1Type, Operand2Type>;
   302→
   303→  dynamic::SelectFrom::Field operator()(const auto& _o) const {
   304→    using DynamicOperatorType = dynamic_operator_t<_op>;
   305→    return dynamic::SelectFrom::Field{dynamic::Operation{DynamicOperatorType{
   306→        .op1 = Ref<dynamic::Operation>::make(
   307→            MakeField<TableTupleType, std::remove_cvref_t<Operand1Type>>{}(
   308→                _o.operand1)
   309→                .val),
   310→        .op2 = Ref<dynamic::Operation>::make(
   311→            MakeField<TableTupleType, std::remove_cvref_t<Operand2Type>>{}(
   312→                _o.operand2)
   313→                .val)}}};
   314→  }
   315→};
   316→
   317→template <class TableTupleType, Operator _op, class Operand1Type,
   318→          class Operand2Type, class Operand3Type>
   319→  requires((num_operands_v<_op>) == 3)
   320→struct MakeField<TableTupleType,
   321→                 Operation<_op, Operand1Type, Operand2Type, Operand3Type>> {
   322→  static constexpr bool is_aggregation = false;
   323→  static constexpr bool is_column = false;
   324→  static constexpr bool is_operation = true;
   325→
   326→  using Name = Nothing;
   327→  using Type =
   328→      underlying_t<TableTupleType, Operation<Operator::replace, Operand1Type,
   329→                                             Operand2Type, Operand3Type>>;
   330→  using Operands = rfl::Tuple<Operand1Type, Operand2Type, Operand3Type>;
   331→
   332→  dynamic::SelectFrom::Field operator()(const auto& _o) const {
   333→    return dynamic::SelectFrom::Field{
   334→        dynamic::Operation{dynamic::Operation::Replace{
   335→            .op1 = Ref<dynamic::Operation>::make(
   336→                MakeField<TableTupleType, std::remove_cvref_t<Operand1Type>>{}(
   337→                    _o.operand1)
   338→                    .val),
   339→            .op2 = Ref<dynamic::Operation>::make(
   340→                MakeField<TableTupleType, std::remove_cvref_t<Operand2Type>>{}(
   341→                    _o.operand2)
   342→                    .val),
   343→            .op3 = Ref<dynamic::Operation>::make(
   344→                MakeField<TableTupleType, std::remove_cvref_t<Operand3Type>>{}(
   345→                    _o.operand3)
   346→                    .val)}}};
   347→  }
   348→};
   349→
   350→template <class TableTupleType, Operator _op, class... OperandTypes>
   351→  requires((num_operands_v<_op>) == std::numeric_limits<size_t>::max())
   352→struct MakeField<TableTupleType, Operation<_op, rfl::Tuple<OperandTypes...>>> {
   353→  static constexpr bool is_aggregation = false;
   354→  static constexpr bool is_column = false;
   355→  static constexpr bool is_operation = true;
   356→
   357→  using Name = Nothing;
   358→  using Type =
   359→      underlying_t<TableTupleType, Operation<_op, rfl::Tuple<OperandTypes...>>>;
   360→  using Operands = rfl::Tuple<OperandTypes...>;
   361→
   362→  dynamic::SelectFrom::Field operator()(const auto& _o) const {
   363→    using DynamicOperatorType = dynamic_operator_t<_op>;
   364→    return dynamic::SelectFrom::Field{dynamic::Operation{DynamicOperatorType{
   365→        .ops = rfl::apply(
   366→            [](const auto&... _ops) {
   367→              return std::vector<Ref<dynamic::Operation>>(
   368→                  {Ref<dynamic::Operation>::make(
   369→                      MakeField<TableTupleType,
   370→                                std::remove_cvref_t<OperandTypes>>{}(_ops)
   371→                          .val)...});
   372→            },
   373→            _o.operand1)}}};
   374→  }
   375→};
   376→
   377→template <class TableTupleType, class ValueType>
   378→inline dynamic::SelectFrom::Field make_field(const ValueType& _val) {
   379→  return MakeField<std::remove_cvref_t<TableTupleType>,
   380→                   std::remove_cvref_t<ValueType>>{}(_val);
   381→}
   382→
   383→}  // namespace sqlgen::transpilation
   384→
   385→#endif
