    16→Result<Ref<Connection>> drop_impl(const Ref<Connection>& _conn,
    17→                                  const dynamic::Drop::What _what,
    18→                                  const bool _if_exists, const bool _cascade) {
    19→  const auto query =
    20→      transpilation::to_drop<ValueType>(_what, _if_exists, _cascade);
    21→  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
    22→    return _conn;
    23→  });
    24→}
    25→
    26→template <class ValueType, class Connection>
    27→  requires is_connection<Connection>
    28→Result<Ref<Connection>> drop_impl(const Result<Ref<Connection>>& _res,
    29→                                  const dynamic::Drop::What _what,
    30→                                  const bool _if_exists, const bool _cascade) {
    31→  return _res.and_then([&](const auto& _conn) {
    32→    return drop_impl<ValueType>(_conn, _what, _if_exists, _cascade);
    33→  });
    34→}
    35→
    36→template <class ValueType>
    37→struct Drop {
    38→  auto operator()(const auto& _conn) const {
    39→    return drop_impl<ValueType>(_conn, what_, if_exists_, cascade_);
    40→  }
    41→  dynamic::Drop::What what_;
    42→  bool cascade_ = false;
    43→  bool if_exists_ = false;
    44→};
