    25→class Connection {
    26→  using ConnPtr = Ref<sqlite3>;
    27→  using StmtPtr = std::shared_ptr<sqlite3_stmt>;
    28→
    29→ public:
    30→  Connection(const std::string& _fname)
    31→      : stmt_(nullptr), conn_(make_conn(_fname)) {}
    32→
    33→  static rfl::Result<Ref<Connection>> make(const std::string& _fname) noexcept;
    34→
    35→  ~Connection() = default;
    36→
    37→  Result<Nothing> begin_transaction() noexcept;
    38→
    39→  Result<Nothing> commit() noexcept;
    40→
    41→  Result<Nothing> execute(const std::string& _sql) noexcept;
    42→
    43→  template <class ItBegin, class ItEnd>
    44→  Result<Nothing> insert(const dynamic::Insert& _stmt, ItBegin _begin,
    45→                         ItEnd _end) noexcept {
    46→    return internal::write_or_insert(
    47→        [&](const auto& _data) { return insert_impl(_stmt, _data); }, _begin,
    48→        _end);
    49→  }
    50→
    51→  template <class ContainerType>
    52→  auto read(const dynamic::SelectFrom& _query) {
    53→    using ValueType = transpilation::value_t<ContainerType>;
    54→    return internal::to_container<ContainerType>(read_impl(_query).transform(
    55→        [](auto&& _it) { return Iterator<ValueType>(std::move(_it)); }));
    56→  }
    57→
    58→  Result<Nothing> rollback() noexcept;
    59→
    60→  std::string to_sql(const dynamic::Statement& _stmt) noexcept {
    61→    return sqlite::to_sql_impl(_stmt);
    62→  }
    63→
    64→  Result<Nothing> start_write(const dynamic::Write& _stmt);
    65→
    66→  Result<Nothing> end_write();
    67→
    68→  template <class ItBegin, class ItEnd>
    69→  Result<Nothing> write(ItBegin _begin, ItEnd _end) {
    70→    return internal::write_or_insert(
    71→        [&](const auto& _data) { return write_impl(_data); }, _begin, _end);
    72→  }
    73→
    74→ private:
    75→  /// Generates the underlying connection.
    76→  static ConnPtr make_conn(const std::string& _fname);
    77→
    78→  /// Actually inserts data based on a prepared statement -
    79→  /// used by both .insert(...) and .write(...).
    80→  Result<Nothing> actual_insert(
    81→      const std::vector<std::vector<std::optional<std::string>>>& _data,
    82→      sqlite3_stmt* _stmt) const noexcept;
    83→
    84→  /// Implements the actual insert.
    85→  Result<Nothing> insert_impl(
    86→      const dynamic::Insert& _stmt,
    87→      const std::vector<std::vector<std::optional<std::string>>>&
    88→          _data) noexcept;
    89→
    90→  /// Generates a prepared statment, usually for inserts.
    91→  Result<StmtPtr> prepare_statement(const std::string& _sql) const noexcept;
    92→
    93→  /// Implements the actual read.
    94→  Result<Ref<IteratorBase>> read_impl(const dynamic::SelectFrom& _query);
    95→
    96→  /// Implements the actual write
    97→  Result<Nothing> write_impl(
    98→      const std::vector<std::vector<std::optional<std::string>>>& _data);
    99→
   100→ private:
   101→  /// A prepared statement - needed for the read and write operations. Note that
   102→  /// we have declared it before conn_, meaning it will be destroyed first.
   103→  StmtPtr stmt_;
   104→
   105→  /// The underlying sqlite3 connection.
   106→  ConnPtr conn_;
   107→};
