    19→TEST(sqlite, test_like) {
    20→  const auto people1 = std::vector<Person>(
    21→      {Person{
    22→           .id = 0, .first_name = "Homer", .last_name = "Simpson", .age = 45},
    23→       Person{.id = 1, .first_name = "Bart", .last_name = "Simpson", .age = 10},
    24→       Person{.id = 2, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
    25→       Person{
    26→           .id = 3, .first_name = "Maggie", .last_name = "Simpson", .age = 0},
    27→       Person{
    28→           .id = 4, .first_name = "Hugo", .last_name = "Simpson", .age = 10}});
    29→
    30→  using namespace sqlgen;
    31→  using namespace sqlgen::literals;
    32→
    33→  const auto conn = sqlite::connect();
    34→
    35→  const auto people2 =
    36→      conn.and_then(write(std::ref(people1)))
    37→          .and_then(sqlgen::read<std::vector<Person>> |
    38→                    where("first_name"_c.like("H%")) | order_by("age"_c))
    39→          .value();
    40→
    41→  const auto people3 =
    42→      conn.and_then(sqlgen::read<std::vector<Person>> |
    43→                    where("first_name"_c.not_like("H%")) | order_by("age"_c))
    44→          .value();
    45→
    46→  const auto people4 =
    47→      conn.and_then(sqlgen::read<std::vector<Person>> |
    48→                    where("first_name"_c.like("O'Reilly")) | order_by("age"_c))
    49→          .value();
