    12→namespace sqlgen::parsing {
    13→
    14→template <class T, bool _auto_incr>
    15→struct Parser<PrimaryKey<T, _auto_incr>> {
    16→  static Result<PrimaryKey<T, _auto_incr>> read(
    17→      const std::optional<std::string>& _str) noexcept {
    18→    return Parser<std::remove_cvref_t<T>>::read(_str).transform(
    19→        [](auto&& _t) -> PrimaryKey<T, _auto_incr> {
    20→          return PrimaryKey<T, _auto_incr>(std::move(_t));
    21→        });
    22→  }
    23→
    24→  static std::optional<std::string> write(
    25→      const PrimaryKey<T, _auto_incr>& _p) noexcept {
    26→    if constexpr (_auto_incr) {
    27→      return std::nullopt;
    28→    } else {
    29→      return Parser<std::remove_cvref_t<T>>::write(_p.value());
    30→    }
    31→  }
    32→
    33→  static dynamic::Type to_type() noexcept {
    34→    return Parser<std::remove_cvref_t<T>>::to_type().visit(
    35→        [](auto _t) -> dynamic::Type {
    36→          _t.properties.auto_incr = _auto_incr;
    37→          _t.properties.primary = true;
    38→          return _t;
    39→        });
    40→  }
    41→};
    42→
    43→}  // namespace sqlgen::parsing
