    13→namespace sqlgen::parsing {
    14→
    15→template <rfl::internal::StringLiteral _format>
    16→struct Parser<Timestamp<_format>> {
    17→  using TSType = Timestamp<_format>;
    18→
    19→  static Result<TSType> read(const std::optional<std::string>& _str) noexcept {
    20→    return Parser<std::string>::read(_str).and_then(
    21→        [](auto&& _s) -> Result<TSType> {
    22→          return TSType::from_string(std::move(_s));
    23→        });
    24→  }
    25→
    26→  static std::optional<std::string> write(const TSType& _t) noexcept {
    27→    return Parser<std::string>::write(_t.str());
    28→  }
    29→
    30→  static dynamic::Type to_type() noexcept {
    31→    const std::string format = typename TSType::Format().str();
    32→    if (format.find("%z") != std::string::npos) {
    33→      return dynamic::types::TimestampWithTZ{};
    34→    } else if (format.find("%H") != std::string::npos ||
    35→               format.find("%M") != std::string::npos ||
    36→               format.find("%S") != std::string::npos ||
    37→               format.find("%R") != std::string::npos ||
    38→               format.find("%T") != std::string::npos) {
    39→      return dynamic::types::Timestamp{};
    40→    } else {
    41→      return dynamic::types::Date{};
    42→    }
    43→  }
    44→};
