    68→std::string aggregation_to_sql(
    69→    const dynamic::Aggregation& _aggregation) noexcept {
    70→  return _aggregation.val.visit([](const auto& _agg) -> std::string {
    71→    using Type = std::remove_cvref_t<decltype(_agg)>;
    72→    std::stringstream stream;
    73→    if constexpr (std::is_same_v<Type, dynamic::Aggregation::Avg>) {
    74→      stream << "AVG(" << operation_to_sql(*_agg.val) << ")";
    75→
    76→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Count>) {
    77→      const auto val =
    78→          std::string(_agg.val && _agg.distinct ? "DISTINCT " : "") +
    79→          (_agg.val ? column_or_value_to_sql(*_agg.val) : std::string("*"));
    80→      stream << "COUNT(" << val << ")";
    81→
    82→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Max>) {
    83→      stream << "MAX(" << operation_to_sql(*_agg.val) << ")";
    84→
    85→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Min>) {
    86→      stream << "MIN(" << operation_to_sql(*_agg.val) << ")";
    87→
    88→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Sum>) {
    89→      stream << "SUM(" << operation_to_sql(*_agg.val) << ")";
    90→
    91→    } else {
    92→      static_assert(rfl::always_false_v<Type>, "Not all cases were covered.");
    93→    }
    94→    return stream.str();
    95→  });
    96→}
    97→
    98→std::string pad_with_zeros(const std::string& _str,
    99→                           const size_t _expected_length) {
   100→  if (_str.size() < _expected_length) {
   101→    return std::string(_expected_length - _str.size(), '0') + _str;
   102→  } else {
   103→    return _str;
   104→  }
   105→}
   106→
   107→std::string column_or_value_to_sql(
   108→    const dynamic::ColumnOrValue& _col) noexcept {
   109→  const auto handle_value = [](const auto& _v) -> std::string {
   110→    using Type = std::remove_cvref_t<decltype(_v)>;
   111→    if constexpr (std::is_same_v<Type, dynamic::String>) {
   112→      return "'" + escape_single_quote(_v.val) + "'";
   113→
   114→    } else if constexpr (std::is_same_v<Type, dynamic::Duration>) {
   115→      const auto prefix = std::string("'") + (_v.val >= 0 ? "+" : "-");
   116→      const auto val = std::abs(_v.val);
   117→      switch (_v.unit) {
   118→        case dynamic::TimeUnit::milliseconds: {
   119→          const auto h = (val / 3600000);
   120→          const auto m = (val / 60000) % 60;
   121→          const auto s = (val / 1000) % 60;
   122→          const auto ms = val % 1000;
   123→          return prefix + pad_with_zeros(std::to_string(h), 2) + ":" +
   124→                 pad_with_zeros(std::to_string(m), 2) + ":" +
   125→                 pad_with_zeros(std::to_string(s), 2) + "." +
   126→                 pad_with_zeros(std::to_string(ms), 3) + "'";
   127→        }
   128→
   129→        case dynamic::TimeUnit::weeks:
   130→          return prefix + std::to_string(val * 7) + " days'";
   131→
   132→        default:
   133→          return prefix + std::to_string(val) + " " +
   134→                 rfl::enum_to_string(_v.unit) + "'";
   135→      }
   136→
   137→    } else if constexpr (std::is_same_v<Type, dynamic::Timestamp>) {
   138→      return std::to_string(_v.seconds_since_unix);
   139→
   140→    } else {
   141→      return std::to_string(_v.val);
   142→    }
   143→  };
   144→
   145→  return _col.visit([&](const auto& _c) -> std::string {
   146→    using Type = std::remove_cvref_t<decltype(_c)>;
   147→    if constexpr (std::is_same_v<Type, dynamic::Column>) {
   148→      if (_c.alias) {
   149→        return *_c.alias + "." + wrap_in_quotes(_c.name);
   150→      } else {
   151→        return wrap_in_quotes(_c.name);
   152→      }
   153→    } else {
   154→      return _c.val.visit(handle_value);
   155→    }
   156→  });
   157→}
   158→
   159→std::string column_to_sql_definition(const dynamic::Column& _col) noexcept {
   160→  return "\"" + _col.name + "\"" + " " + type_to_sql(_col.type) +
   161→         properties_to_sql(
   162→             _col.type.visit([](const auto& _t) { return _t.properties; }));
   163→}
   164→
   165→std::string condition_to_sql(const dynamic::Condition& _cond) noexcept {
   166→  return _cond.val.visit(
   167→      [&](const auto& _c) { return condition_to_sql_impl(_c); });
   168→}
   169→
   170→template <class ConditionType>
   171→std::string condition_to_sql_impl(const ConditionType& _condition) noexcept {
   172→  using namespace std::ranges::views;
   173→
   174→  using C = std::remove_cvref_t<ConditionType>;
   175→
   176→  std::stringstream stream;
   177→
   178→  if constexpr (std::is_same_v<C, dynamic::Condition::And>) {
   179→    stream << "(" << condition_to_sql(*_condition.cond1) << ") AND ("
   180→           << condition_to_sql(*_condition.cond2) << ")";
   181→
   182→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Equal>) {
   183→    stream << operation_to_sql(_condition.op1) << " = "
   184→           << operation_to_sql(_condition.op2);
   185→
   186→  } else if constexpr (std::is_same_v<C, dynamic::Condition::GreaterEqual>) {
   187→    stream << operation_to_sql(_condition.op1)
   188→           << " >= " << operation_to_sql(_condition.op2);
   189→
   190→  } else if constexpr (std::is_same_v<C, dynamic::Condition::GreaterThan>) {
   191→    stream << operation_to_sql(_condition.op1) << " > "
   192→           << operation_to_sql(_condition.op2);
   193→
   194→  } else if constexpr (std::is_same_v<C, dynamic::Condition::In>) {
   195→    stream << operation_to_sql(_condition.op) << " IN ("
   196→           << internal::strings::join(
   197→                  ", ",
   198→                  internal::collect::vector(_condition.patterns |
   199→                                            transform(column_or_value_to_sql)))
   200→           << ")";
   201→
   202→  } else if constexpr (std::is_same_v<C, dynamic::Condition::IsNull>) {
   203→    stream << operation_to_sql(_condition.op) << " IS NULL";
   204→
   205→  } else if constexpr (std::is_same_v<C, dynamic::Condition::IsNotNull>) {
   206→    stream << operation_to_sql(_condition.op) << " IS NOT NULL";
   207→
   208→  } else if constexpr (std::is_same_v<C, dynamic::Condition::LesserEqual>) {
   209→    stream << operation_to_sql(_condition.op1)
   210→           << " <= " << operation_to_sql(_condition.op2);
   211→
   212→  } else if constexpr (std::is_same_v<C, dynamic::Condition::LesserThan>) {
   213→    stream << operation_to_sql(_condition.op1) << " < "
   214→           << operation_to_sql(_condition.op2);
   215→
   216→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Like>) {
   217→    stream << operation_to_sql(_condition.op) << " LIKE "
   218→           << column_or_value_to_sql(_condition.pattern);
   219→
   220→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Not>) {
   221→    stream << "NOT (" << condition_to_sql(*_condition.cond) << ")";
   222→
   223→  } else if constexpr (std::is_same_v<C, dynamic::Condition::NotEqual>) {
   224→    stream << operation_to_sql(_condition.op1)
   225→           << " != " << operation_to_sql(_condition.op2);
   226→
   227→  } else if constexpr (std::is_same_v<C, dynamic::Condition::NotLike>) {
   228→    stream << operation_to_sql(_condition.op) << " NOT LIKE "
   229→           << column_or_value_to_sql(_condition.pattern);
   230→
   231→  } else if constexpr (std::is_same_v<C, dynamic::Condition::NotIn>) {
   232→    stream << operation_to_sql(_condition.op) << " NOT IN ("
   233→           << internal::strings::join(
   234→                  ", ",
   235→                  internal::collect::vector(_condition.patterns |
   236→                                            transform(column_or_value_to_sql)))
   237→           << ")";
   238→
   239→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Or>) {
   240→    stream << "(" << condition_to_sql(*_condition.cond1) << ") OR ("
   241→           << condition_to_sql(*_condition.cond2) << ")";
   242→
   243→  } else {
   244→    static_assert(rfl::always_false_v<C>, "Not all cases were covered.");
   245→  }
   246→  return stream.str();
   247→}
   248→
   249→std::string create_index_to_sql(const dynamic::CreateIndex& _stmt) noexcept {
   250→  using namespace std::ranges::views;
   251→
   252→  const auto in_quotes = [](const std::string& _str) -> std::string {
   253→    return "\"" + _str + "\"";
   254→  };
   255→
   256→  std::stringstream stream;
   257→
   258→  if (_stmt.unique) {
   259→    stream << "CREATE UNIQUE INDEX ";
   260→  } else {
   261→    stream << "CREATE INDEX ";
   262→  }
   263→
   264→  if (_stmt.if_not_exists) {
   265→    stream << "IF NOT EXISTS ";
   266→  }
   267→
   268→  if (_stmt.table.schema) {
   269→    stream << "\"" << *_stmt.table.schema << "\".";
   270→  }
   271→  stream << "\"" << _stmt.name << "\" ";
   272→
   273→  stream << "ON " << "\"" << _stmt.table.name << "\"";
   274→
   275→  stream << "(";
   276→  stream << internal::strings::join(
   277→      ", ", internal::collect::vector(_stmt.columns | transform(in_quotes)));
   278→  stream << ")";
   279→
   280→  if (_stmt.where) {
   281→    stream << " WHERE " << condition_to_sql(*_stmt.where);
   282→  }
   283→
   284→  stream << ";";
   285→
   286→  return stream.str();
   287→}
   288→
   289→std::string create_table_to_sql(const dynamic::CreateTable& _stmt) noexcept {
   290→  using namespace std::ranges::views;
   291→
   292→  const auto col_to_sql = [&](const auto& _col) {
   293→    return column_to_sql_definition(_col);
   294→  };
   295→
   296→  std::stringstream stream;
   297→  stream << "CREATE TABLE ";
   298→
   299→  if (_stmt.if_not_exists) {
   300→    stream << "IF NOT EXISTS ";
   301→  }
   302→
   303→  if (_stmt.table.schema) {
   304→    stream << "\"" << *_stmt.table.schema << "\".";
   305→  }
   306→  stream << "\"" << _stmt.table.name << "\" ";
   307→
   308→  stream << "(";
   309→  stream << internal::strings::join(
   310→      ", ", internal::collect::vector(_stmt.columns | transform(col_to_sql)));
   311→  stream << ");";
   312→
   313→  return stream.str();
   314→}
   315→
   316→std::string create_as_to_sql(const dynamic::CreateAs& _stmt) noexcept {
   317→  std::stringstream stream;
   318→
   319→  stream << "CREATE "
   320→         << internal::strings::replace_all(
   321→                internal::strings::to_upper(rfl::enum_to_string(_stmt.what)),
   322→                "_", " ")
   323→         << " ";
   324→
   325→  if (_stmt.if_not_exists) {
   326→    stream << "IF NOT EXISTS ";
   327→  }
   328→
   329→  if (_stmt.table_or_view.schema) {
   330→    stream << wrap_in_quotes(*_stmt.table_or_view.schema) << ".";
   331→  }
   332→  stream << wrap_in_quotes(_stmt.table_or_view.name) << " AS ";
   333→
   334→  stream << select_from_to_sql(_stmt.query);
   335→
   336→  return stream.str();
   337→}
