   339→std::string delete_from_to_sql(const dynamic::DeleteFrom& _stmt) noexcept {
   340→  std::stringstream stream;
   341→
   342→  stream << "DELETE FROM ";
   343→
   344→  if (_stmt.table.schema) {
   345→    stream << "\"" << *_stmt.table.schema << "\".";
   346→  }
   347→  stream << "\"" << _stmt.table.name << "\"";
   348→
   349→  if (_stmt.where) {
   350→    stream << " WHERE " << condition_to_sql(*_stmt.where);
   351→  }
   352→
   353→  stream << ";";
   354→
   355→  return stream.str();
