   357→
   358→std::string drop_to_sql(const dynamic::Drop& _stmt) noexcept {
   359→  std::stringstream stream;
   360→
   361→  stream << "DROP "
   362→         << internal::strings::replace_all(
   363→                internal::strings::to_upper(rfl::enum_to_string(_stmt.what)),
   364→                "_", " ")
   365→         << " ";
   366→
   367→  if (_stmt.if_exists) {
   368→    stream << "IF EXISTS ";
   369→  }
   370→
   371→  if (_stmt.table.schema) {
   372→    stream << "\"" << *_stmt.table.schema << "\".";
   373→  }
   374→  stream << "\"" << _stmt.table.name << "\"";
   375→
