   658→std::string select_from_to_sql(const dynamic::SelectFrom& _stmt) noexcept {
   659→  using namespace std::ranges::views;
   660→
   661→  const auto order_by_to_str = [](const auto& _w) -> std::string {
   662→    return column_or_value_to_sql(_w.column) + (_w.desc ? " DESC" : "");
   663→  };
   664→
   665→  std::stringstream stream;
   666→
   667→  stream << "SELECT ";
   668→  stream << internal::strings::join(
   669→      ", ", internal::collect::vector(_stmt.fields | transform(field_to_str)));
   670→
   671→  stream << " FROM " << table_or_query_to_sql(_stmt.table_or_query);
   672→
   673→  if (_stmt.alias) {
   674→    stream << " " << *_stmt.alias;
   675→  }
   676→
   677→  if (_stmt.joins) {
   678→    stream << " "
   679→           << internal::strings::join(
   680→                  " ", internal::collect::vector(*_stmt.joins |
   681→                                                 transform(join_to_sql)));
   682→  }
   683→
   684→  if (_stmt.where) {
   685→    stream << " WHERE " << condition_to_sql(*_stmt.where);
   686→  }
   687→
   688→  if (_stmt.group_by) {
   689→    stream << " GROUP BY "
   690→           << internal::strings::join(
   691→                  ", ",
   692→                  internal::collect::vector(_stmt.group_by->columns |
   693→                                            transform(column_or_value_to_sql)));
   694→  }
   695→
   696→  if (_stmt.order_by) {
   697→    stream << " ORDER BY "
   698→           << internal::strings::join(
   699→                  ", ", internal::collect::vector(_stmt.order_by->columns |
   700→                                                  transform(order_by_to_str)));
   701→  }
   702→
   703→  if (_stmt.limit) {
   704→    stream << " LIMIT " << _stmt.limit->val;
   705→  }
   706→
   707→  return stream.str();
   708→}
