   722→std::string to_sql_impl(const dynamic::Statement& _stmt) noexcept {
   723→  return _stmt.visit([&](const auto& _s) -> std::string {
   724→    using S = std::remove_cvref_t<decltype(_s)>;
   725→    if constexpr (std::is_same_v<S, dynamic::CreateIndex>) {
   726→      return create_index_to_sql(_s);
   727→
   728→    } else if constexpr (std::is_same_v<S, dynamic::CreateTable>) {
   729→      return create_table_to_sql(_s);
   730→
   731→    } else if constexpr (std::is_same_v<S, dynamic::CreateAs>) {
   732→      return create_as_to_sql(_s);
   733→
   734→    } else if constexpr (std::is_same_v<S, dynamic::DeleteFrom>) {
   735→      return delete_from_to_sql(_s);
   736→
   737→    } else if constexpr (std::is_same_v<S, dynamic::Drop>) {
   738→      return drop_to_sql(_s);
   739→
   740→    } else if constexpr (std::is_same_v<S, dynamic::Insert>) {
   741→      return insert_or_write_to_sql(_s);
   742→
   743→    } else if constexpr (std::is_same_v<S, dynamic::SelectFrom>) {
   744→      return select_from_to_sql(_s);
   745→
   746→    } else if constexpr (std::is_same_v<S, dynamic::Update>) {
   747→      return update_to_sql(_s);
   748→
   749→    } else if constexpr (std::is_same_v<S, dynamic::Write>) {
   750→      return insert_or_write_to_sql(_s);
   751→
   752→    } else {
   753→      static_assert(rfl::always_false_v<S>, "Unsupported type.");
   754→    }
   755→  });
   756→}
