   102→  const auto sql = to_sql_impl(_query);
   103→
   104→  sqlite3_stmt* p_stmt = nullptr;
   105→
   106→  sqlite3_prepare(conn_.get(), /* Database handle */
   107→                  sql.c_str(), /* SQL statement, UTF-8 encoded */
   108→                  sql.size(),  /* Maximum length of zSql in bytes. */
   109→                  &p_stmt,     /* OUT: Statement handle */
   110→                  nullptr      /* OUT: Pointer to unused portion of zSql */
   111→  );
