   252→  const auto in_quotes = [](const std::string& _str) -> std::string {
   253→    return "\"" + _str + "\"";
   254→  };
   255→
   256→  std::stringstream stream;
   257→
   258→  if (_stmt.unique) {
   259→    stream << "CREATE UNIQUE INDEX ";
   260→  } else {
   261→    stream << "CREATE INDEX ";
   262→  }
   263→
   264→  if (_stmt.if_not_exists) {
   265→    stream << "IF NOT EXISTS ";
   266→  }
   267→
   268→  if (_stmt.table.schema) {
   269→    stream << "\"" << *_stmt.table.schema << "\".";
   270→  }
   271→  stream << "\"" << _stmt.name << "\" ";
   272→
   273→  stream << "ON " << "\"" << _stmt.table.name << "\"";
   274→
   275→  stream << "(";
   276→  stream << internal::strings::join(
   277→      ", ", internal::collect::vector(_stmt.columns | transform(in_quotes)));
   278→  stream << ")";
   279→
   280→  if (_stmt.where) {
   281→    stream << " WHERE " << condition_to_sql(*_stmt.where);
   282→  }
   283→
   284→  stream << ";";
   285→
   286→  return stream.str();
   287→}
