   397→template <class InsertOrWrite>
   398→std::string insert_or_write_to_sql(const InsertOrWrite& _stmt) noexcept {
   399→  using namespace std::ranges::views;
   400→
   401→  const auto in_quotes = [](const std::string& _str) -> std::string {
   402→    return "\"" + _str + "\"";
   403→  };
   404→
   405→  const auto to_questionmark = [](const std::string&) -> std::string {
   406→    return "?";
   407→  };
   408→
   409→  const auto as_excluded = [](const std::string& _str) -> std::string {
   410→    return _str + "=excluded." + _str;
   411→  };
   412→
   413→  std::stringstream stream;
   414→  stream << "INSERT INTO ";
   415→
   416→  if (_stmt.table.schema) {
   417→    stream << wrap_in_quotes(*_stmt.table.schema) << ".";
   418→  }
   419→  stream << wrap_in_quotes(_stmt.table.name);
   420→
   421→  stream << " (";
   422→  stream << internal::strings::join(
   423→      ", ", internal::collect::vector(_stmt.columns | transform(in_quotes)));
   424→  stream << ")";
   425→
   426→  stream << " VALUES (";
   427→  stream << internal::strings::join(
   428→      ", ",
   429→      internal::collect::vector(_stmt.columns | transform(to_questionmark)));
   430→  stream << ")";
   431→
   432→  if constexpr (std::is_same_v<InsertOrWrite, dynamic::Insert>) {
   433→    if (_stmt.or_replace) {
   434→      stream << " ON CONFLICT (";
   435→      stream << internal::strings::join(
   436→          ", ", internal::collect::vector(_stmt.constraints));
   437→      stream << ")";
   438→
   439→      stream << " DO UPDATE SET ";
   440→      stream << internal::strings::join(
   441→          ", ",
   442→          internal::collect::vector(_stmt.columns | transform(as_excluded)));
   443→    }
   444→  }
   445→
   446→  stream << ';';
   447→  return stream.str();
   448→}
