   146→  }
   147→
   148→  template <class OtherTableOrQueryType, class ConditionType,
   149→            rfl::internal::StringLiteral _alias, transpilation::JoinType _how>
   150→  friend auto operator|(
   151→      const SelectFrom& _s,
   152→      const transpilation::Join<OtherTableOrQueryType, ConditionType, _alias,
   153→                                _how>& _join) {
   154→    static_assert(std::is_same_v<WhereType, Nothing>,
   155→                  "You cannot call where(...) before a join.");
   156→    static_assert(std::is_same_v<GroupByType, Nothing>,
   157→                  "You cannot call group_by(...) before a join.");
   158→    static_assert(std::is_same_v<OrderByType, Nothing>,
   159→                  "You cannot call order_by(...) before a join.");
   160→    static_assert(std::is_same_v<LimitType, Nothing>,
   161→                  "You cannot call limit(...) before a join.");
   162→    static_assert(std::is_same_v<ToType, Nothing>,
   163→                  "You cannot call to<...> before a join.");
   164→
