    66→template <class ContainerType>
    67→auto write(const auto& _conn, const ContainerType& _container) noexcept {
    68→  if constexpr (std::ranges::input_range<std::remove_cvref_t<ContainerType>>) {
    69→    return write(_conn, _container.begin(), _container.end());
    70→  } else {
    71→    return write(_conn, &_container, &_container + 1);
    72→  }
    73→}
