   157→                  "You cannot call group_by(...) before a join.");
   158→    static_assert(std::is_same_v<OrderByType, Nothing>,
   159→                  "You cannot call order_by(...) before a join.");
   160→    static_assert(std::is_same_v<LimitType, Nothing>,
   161→                  "You cannot call limit(...) before a join.");
   162→    static_assert(std::is_same_v<ToType, Nothing>,
   163→                  "You cannot call to<...> before a join.");
   164→
   165→    if constexpr (std::is_same_v<JoinsType, Nothing>) {
