     1→#ifndef SQLGEN_TRANSPILATION_TO_INSERT_OR_WRITE_HPP_
     2→#define SQLGEN_TRANSPILATION_TO_INSERT_OR_WRITE_HPP_
     3→
     4→#include <ranges>
     5→#include <rfl.hpp>
     6→#include <string>
     7→#include <type_traits>
     8→#include <utility>
     9→#include <vector>
    10→
    11→#include "../dynamic/Table.hpp"
    12→#include "../internal/collect/vector.hpp"
    13→#include "../internal/remove_auto_incr_primary_t.hpp"
    14→#include "get_schema.hpp"
    15→#include "get_tablename.hpp"
    16→#include "make_columns.hpp"
    17→
    18→namespace sqlgen::transpilation {
    19→
    20→template <class T, class InsertOrWrite>
    21→  requires std::is_class_v<std::remove_cvref_t<T>> &&
    22→           std::is_aggregate_v<std::remove_cvref_t<T>>
    23→InsertOrWrite to_insert_or_write(bool or_replace) {
    24→  using namespace std::ranges::views;
    25→
    26→  using NamedTupleType = sqlgen::internal::remove_auto_incr_primary_t<
    27→      rfl::named_tuple_t<std::remove_cvref_t<T>>>;
    28→  using Fields = typename NamedTupleType::Fields;
    29→
    30→  const auto columns = make_columns<Fields>(
    31→      std::make_integer_sequence<int, rfl::tuple_size_v<Fields>>());
    32→
    33→  const auto get_name = [](const auto& _col) { return _col.name; };
    34→
    35→  auto result = InsertOrWrite{
    36→      .table =
    37→          dynamic::Table{.name = get_tablename<T>(), .schema = get_schema<T>()},
    38→      .columns =
    39→          sqlgen::internal::collect::vector(columns | transform(get_name))};
    40→
    41→  if constexpr (std::is_same_v<InsertOrWrite, dynamic::Insert>) {
    42→    const auto is_non_primary = [](const auto& _c) {
    43→      return _c.type.visit(
    44→          [](const auto& _t) { return !_t.properties.primary; });
    45→    };
    46→
    47→    const auto is_constraint = [](const auto& _c) {
    48→      return _c.type.visit([](const auto& _t) {
    49→        return _t.properties.primary || _t.properties.unique;
    50→      });
    51→    };
    52→
    53→    result.or_replace = or_replace;
    54→    result.non_primary_keys = sqlgen::internal::collect::vector(
    55→        columns | filter(is_non_primary) | transform(get_name));
    56→    if (or_replace) {
    57→      result.constraints = sqlgen::internal::collect::vector(
    58→          columns | filter(is_constraint) | transform(get_name));
    59→    }
    60→  }
    61→
    62→  return result;
    63→}
    64→
    65→template <class T, class InsertOrWrite>
    66→  requires std::is_class_v<std::remove_cvref_t<T>> &&
    67→           std::is_aggregate_v<std::remove_cvref_t<T>>
    68→InsertOrWrite to_insert_or_write() {
    69→  return to_insert_or_write<T, InsertOrWrite>(false);
    70→}
    71→
    72→}  // namespace sqlgen::transpilation
    73→
    74→#endif
    75→

