    88→template <class TableTupleType, class AliasType, class FieldsType,
    89→          class TableOrQueryType, class JoinsType, class WhereType,
    90→          class GroupByType, class OrderByType, class LimitType,
    91→          class ContainerType, class Connection>
    92→  requires is_connection<Connection>
    93→auto select_from_impl(const Result<Ref<Connection>>& _res,
    94→                      const FieldsType& _fields,
    95→                      const TableOrQueryType& _table_or_query,
    96→                      const JoinsType& _joins, const WhereType& _where,
    97→                      const LimitType& _limit) {
    98→  return _res.and_then([&](const auto& _conn) {
    99→    return select_from_impl<TableTupleType, AliasType, FieldsType,
   100→                            TableOrQueryType, JoinsType, WhereType, GroupByType,
   101→                            OrderByType, LimitType, ContainerType>(
   102→        _conn, _fields, _table_or_query, _joins, _where, _limit);
   103→  });
   104→}
   105→
   106→template <class TableOrQueryType, class AliasType, class FieldsType,
   107→          class JoinsType = Nothing, class WhereType = Nothing,
   108→          class GroupByType = Nothing, class OrderByType = Nothing,
   109→          class LimitType = Nothing, class ToType = Nothing>
   110→struct SelectFrom {
   111→  auto operator()(const auto& _conn) const {
   112→    using TableTupleType =
   113→        transpilation::table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   114→
   115→    if constexpr (std::is_same_v<ToType, Nothing> ||
   116→                  std::ranges::input_range<std::remove_cvref_t<ToType>>) {
   117→      using IteratorType = internal::iterator_t<
   118→          transpilation::fields_to_named_tuple_t<TableTupleType, FieldsType>,
   119→          decltype(_conn)>;
   120→
   121→      using ContainerType = std::conditional_t<std::is_same_v<ToType, Nothing>,
   122→                                               Range<IteratorType>, ToType>;
   123→      return select_from_impl<
   124→          TableTupleType, AliasType, FieldsType, TableOrQueryType, JoinsType,
   125→          WhereType, GroupByType, OrderByType, LimitType, ContainerType>(
   126→          _conn, fields_, from_, joins_, where_, limit_);
   127→
   128→    } else {
   129→      const auto extract_result = [](auto&& _vec) -> Result<ToType> {
   130→        if (_vec.size() != 1) {
   131→          return error(
   132→              "Because the type provided to to<...> was not a container, the "
   133→              "query needs to return exactly one result, but it did return " +
   134→              std::to_string(_vec.size()) + " results.");
   135→        }
   136→        return std::move(_vec[0]);
   137→      };
   138→
   139→      return select_from_impl<TableTupleType, AliasType, FieldsType,
   140→                              TableOrQueryType, JoinsType, WhereType,
   141→                              GroupByType, OrderByType, LimitType,
   142→                              std::vector<std::remove_cvref_t<ToType>>>(
   143→                 _conn, fields_, from_, joins_, where_, limit_)
   144→          .and_then(extract_result);
   145→    }
   146→  }
   147→
   148→  template <class OtherTableOrQueryType, class ConditionType,
   149→            rfl::internal::StringLiteral _alias, transpilation::JoinType _how>
   150→  friend auto operator|(
   151→      const SelectFrom& _s,
   152→      const transpilation::Join<OtherTableOrQueryType, ConditionType, _alias,
   153→                                _how>& _join) {
   154→    static_assert(std::is_same_v<WhereType, Nothing>,
   155→                  "You cannot call where(...) before a join.");
   156→    static_assert(std::is_same_v<GroupByType, Nothing>,
   157→                  "You cannot call group_by(...) before a join.");
   158→    static_assert(std::is_same_v<OrderByType, Nothing>,
   159→                  "You cannot call order_by(...) before a join.");
   160→    static_assert(std::is_same_v<LimitType, Nothing>,
   161→                  "You cannot call limit(...) before a join.");
   162→    static_assert(std::is_same_v<ToType, Nothing>,
   163→                  "You cannot call to<...> before a join.");
   164→
   165→    if constexpr (std::is_same_v<JoinsType, Nothing>) {
   166→      using NewJoinsType =
   167→          rfl::Tuple<transpilation::Join<OtherTableOrQueryType, ConditionType,
   168→                                         _alias, _how>>;
   169→
   170→      return SelectFrom<TableOrQueryType, AliasType, FieldsType, NewJoinsType,
   171→                        WhereType, GroupByType, OrderByType, LimitType, ToType>{
   172→          .fields_ = _s.fields_,
   173→          .from_ = _s.from_,
   174→          .joins_ = NewJoinsType(_join)};
   175→
   176→    } else {
   177→      using TupleType =
   178→          rfl::Tuple<transpilation::Join<OtherTableOrQueryType, ConditionType,
   179→                                         _alias, _how>>;
   180→
   181→      const auto joins = rfl::tuple_cat(_s.joins_, TupleType(_join));
   182→
   183→      using NewJoinsType = std::remove_cvref_t<decltype(joins)>;
   184→
   185→      return SelectFrom<TableOrQueryType, AliasType, FieldsType, NewJoinsType,
   186→                        WhereType, GroupByType, OrderByType, LimitType, ToType>{
   187→          .fields_ = _s.fields_, .from_ = _s.from_, .joins_ = joins};
   188→    }
   189→  }
   190→
   191→  template <class ConditionType>
   192→  friend auto operator|(const SelectFrom& _s,
   193→                        const Where<ConditionType>& _where) {
   194→    static_assert(std::is_same_v<WhereType, Nothing>,
   195→                  "You cannot call where(...) twice (but you can apply more "
   196→                  "than one condition by combining them with && or ||).");
   197→    static_assert(std::is_same_v<GroupByType, Nothing>,
   198→                  "You cannot call group_by(...) before where(...).");
   199→    static_assert(std::is_same_v<OrderByType, Nothing>,
   200→                  "You cannot call order_by(...) before where(...).");
   201→    static_assert(std::is_same_v<LimitType, Nothing>,
   202→                  "You cannot call limit(...) before where(...).");
   203→    static_assert(std::is_same_v<ToType, Nothing>,
   204→                  "You cannot call to<...> before where(...).");
   205→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   206→                      ConditionType, GroupByType, OrderByType, LimitType,
   207→                      ToType>{.fields_ = _s.fields_,
   208→                              .from_ = _s.from_,
   209→                              .joins_ = _s.joins_,
   210→                              .where_ = _where.condition};
   211→  }
   212→
   213→  template <class... ColTypes>
   214→  friend auto operator|(const SelectFrom& _s, const GroupBy<ColTypes...>&) {
   215→    static_assert(
   216→        std::is_same_v<GroupByType, Nothing>,
   217→        "You cannot call group_by(...) twice (but you can group by more "
   218→        "than one column).");
   219→    static_assert(std::is_same_v<OrderByType, Nothing>,
   220→                  "You cannot call order_by(...) before group_by(...).");
   221→    static_assert(std::is_same_v<LimitType, Nothing>,
   222→                  "You cannot call limit(...) before group_by(...).");
   223→    static_assert(std::is_same_v<ToType, Nothing>,
   224→                  "You cannot call to<...> before group_by(...).");
   225→    static_assert(sizeof...(ColTypes) != 0,
   226→                  "You must assign at least one column to group_by.");
   227→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   228→                      WhereType,
   229→                      transpilation::group_by_t<TableOrQueryType,
   230→                                                typename ColTypes::ColType...>,
   231→                      OrderByType, LimitType, ToType>{.fields_ = _s.fields_,
   232→                                                      .from_ = _s.from_,
   233→                                                      .joins_ = _s.joins_,
   234→                                                      .where_ = _s.where_};
   235→  }
   236→
   237→  template <class... ColTypes>
   238→  friend auto operator|(const SelectFrom& _s, const OrderBy<ColTypes...>&) {
   239→    static_assert(
   240→        std::is_same_v<OrderByType, Nothing>,
   241→        "You cannot call order_by(...) twice (but you can order by more "
   242→        "than one column).");
   243→    static_assert(std::is_same_v<LimitType, Nothing>,
   244→                  "You cannot call limit(...) before order_by(...).");
   245→    static_assert(std::is_same_v<ToType, Nothing>,
   246→                  "You cannot call to<...> before order_by(...).");
   247→    static_assert(sizeof...(ColTypes) != 0,
   248→                  "You must assign at least one column to order_by.");
   249→
   250→    using TableTupleType =
   251→        transpilation::table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   252→
   253→    using NewOrderByType = transpilation::order_by_t<
   254→        TableTupleType, GroupByType,
   255→        typename std::remove_cvref_t<ColTypes>::ColType...>;
   256→
   257→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   258→                      WhereType, GroupByType, NewOrderByType, LimitType,
   259→                      ToType>{.fields_ = _s.fields_,
   260→                              .from_ = _s.from_,
   261→                              .joins_ = _s.joins_,
   262→                              .where_ = _s.where_};
   263→  }
   264→
   265→  friend auto operator|(const SelectFrom& _s, const Limit& _limit) {
   266→    static_assert(std::is_same_v<LimitType, Nothing>,
   267→                  "You cannot call limit twice.");
   268→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   269→                      WhereType, GroupByType, OrderByType, Limit, ToType>{
   270→        .fields_ = _s.fields_,
   271→        .from_ = _s.from_,
   272→        .joins_ = _s.joins_,
   273→        .where_ = _s.where_,
   274→        .limit_ = _limit};
   275→  }
   276→
   277→  template <class NewToType>
