    85→template <class ContainerType>
    86→auto insert_or_replace(const auto& _conn, const ContainerType& _data) {
    87→  if constexpr (std::ranges::input_range<std::remove_cvref_t<ContainerType>>) {
    88→    static_assert(
    89→        internal::has_constraint_v<typename ContainerType::value_type>,
    90→        "The table must have a primary key or unique column for "
    91→        "insert_or_replace(...) to work.");
    92→  } else {
    93→    static_assert(internal::has_constraint_v<ContainerType>,
    94→                  "The table must have a primary key or unique column for "
    95→                  "insert_or_replace(...) to work.");
    96→  }
    97→  return insert_impl(_conn, _data, true);
    98→}
