    22→  requires is_connection<Connection>
    23→Result<Ref<Connection>> insert_impl(const Ref<Connection>& _conn,
    24→                                    ItBegin _begin, ItEnd _end,
    25→                                    bool _or_replace) {
    26→  using T =
    27→      std::remove_cvref_t<typename std::iterator_traits<ItBegin>::value_type>;
    28→
    29→  const auto insert_stmt =
    30→      transpilation::to_insert_or_write<T, dynamic::Insert>(_or_replace);
    31→
    32→  return _conn->insert(insert_stmt, _begin, _end).transform([&](const auto&) {
    33→    return _conn;
    34→  });
    35→}
    36→
    37→template <class ItBegin, class ItEnd, class Connection>
    38→  requires is_connection<Connection>
    39→Result<Ref<Connection>> insert_impl(const Result<Ref<Connection>>& _res,
    40→                                    ItBegin _begin, ItEnd _end,
    41→                                    bool _or_replace) {
    42→  return _res.and_then([&](const auto& _conn) {
    43→    return insert_impl(_conn, _begin, _end, _or_replace);
    44→  });
    45→}
    46→
    47→template <class ContainerType>
    48→auto insert_impl(const auto& _conn, const ContainerType& _data,
    49→                 bool _or_replace) {
    50→  if constexpr (std::ranges::input_range<std::remove_cvref_t<ContainerType>>) {
    51→    return insert_impl(_conn, _data.begin(), _data.end(), _or_replace);
    52→  } else {
    53→    return insert_impl(_conn, &_data, &_data + 1, _or_replace);
    54→  }
    55→}
