    16→namespace sqlgen {
    17→
    18→template <class Connection>
    19→class Session {
    20→ public:
    21→  using ConnPtr = Ref<Connection>;
    22→
    23→  Session(const Ref<Connection>& _conn, const Ref<std::atomic_flag>& _flag)
    24→      : conn_(_conn), flag_(_flag.ptr()) {}
    25→
    26→  Session(const Session<Connection>& _other) = delete;
    27→
    28→  Session(Session<Connection>&& _other)
    29→      : conn_(std::move(_other.conn_)), flag_(_other.flag_) {
    30→    _other.flag_.reset();
    31→  }
    32→
    33→  ~Session() {
    34→    if (flag_) {
    35→      flag_->clear();
    36→    }
    37→  }
    38→
    39→  Result<Nothing> begin_transaction() { return conn_->begin_transaction(); }
    40→
    41→  Result<Nothing> commit() { return conn_->commit(); }
    42→
    43→  Result<Nothing> execute(const std::string& _sql) {
    44→    return conn_->execute(_sql);
    45→  }
    46→
    47→  template <class ItBegin, class ItEnd>
    48→  Result<Nothing> insert(const dynamic::Insert& _stmt, ItBegin _begin,
    49→                         ItEnd _end) {
    50→    return conn_->insert(_stmt, _begin, _end);
    51→  }
    52→
    53→  Session& operator=(const Session& _other) = delete;
    54→
    55→  Session& operator=(Session&& _other) noexcept {
    56→    if (this == &_other) {
    57→      return *this;
    58→    }
    59→    conn_ = std::move(_other.conn_);
    60→    flag_ = _other.flag_;
    61→    _other.flag_.reset();
    62→    return *this;
    63→  }
    64→
    65→  template <class ContainerType>
    66→  Result<ContainerType> read(const dynamic::SelectFrom& _query) {
    67→    return conn_->template read<ContainerType>(_query);
    68→  }
    69→
    70→  Result<Nothing> rollback() noexcept { return conn_->rollback(); }
    71→
    72→  std::string to_sql(const dynamic::Statement& _stmt) noexcept {
    73→    return conn_->to_sql(_stmt);
    74→  }
    75→
    76→  Result<Nothing> start_write(const dynamic::Write& _stmt) {
    77→    return conn_->start_write(_stmt);
    78→  }
    79→
    80→  Result<Nothing> end_write() { return conn_->end_write(); }
    81→
    82→  template <class ItBegin, class ItEnd>
    83→  Result<Nothing> write(ItBegin _begin, ItEnd _end) {
    84→    return conn_->write(_begin, _end);
    85→  }
    86→
    87→ private:
    88→  /// The underlying connection object.
    89→  ConnPtr conn_;
    90→
    91→  /// The flag corresponding to the object - as long as this is true, we have
    92→  /// ownership.
    93→  std::shared_ptr<std::atomic_flag> flag_;
    94→};
    95→
    96→}  // namespace sqlgen
    97→
    98→#endif
