    10→namespace test_is_null {
    11→
    12→struct Person {
    13→  sqlgen::PrimaryKey<uint32_t> id;
    14→  std::string first_name;
    15→  std::string last_name;
    16→  std::optional<int> age;
    17→};
    18→
    19→TEST(sqlite, test_is_null) {
    20→  const auto people1 = std::vector<Person>(
    21→      {Person{.id = 0, .first_name = "Homer", .last_name = "Simpson"},
    22→       Person{.id = 1, .first_name = "Bart", .last_name = "Simpson", .age = 10},
    23→       Person{.id = 2, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
    24→       Person{
    25→           .id = 3, .first_name = "Maggie", .last_name = "Simpson", .age = 0},
    26→       Person{.id = 4, .first_name = "Hugo", .last_name = "Simpson"}});
    27→
    28→  using namespace sqlgen;
    29→  using namespace sqlgen::literals;
    30→
    31→  const auto conn = sqlite::connect();
    32→
    33→  const auto people2 =
    34→      conn.and_then(write(std::ref(people1)))
    35→          .and_then(sqlgen::read<std::vector<Person>> |
    36→                    where("age"_c.is_null()) | order_by("first_name"_c.desc()))
    37→          .value();
    38→
    39→  const auto people3 =
    40→      conn.and_then(sqlgen::read<std::vector<Person>> |
    41→                    where("age"_c.is_not_null()) | order_by("age"_c))
    42→          .value();
    43→
    44→  const std::string expected1 =
    45→      R"([{"id":4,"first_name":"Hugo","last_name":"Simpson"},{"id":0,"first_name":"Homer","last_name":"Simpson"}])";
    46→
    47→  const std::string expected2 =
    48→      R"([{"id":3,"first_name":"Maggie","last_name":"Simpson","age":0},{"id":2,"first_name":"Lisa","last_name":"Simpson","age":8},{"id":1,"first_name":"Bart","last_name":"Simpson","age":10}])";
    49→
    50→  EXPECT_EQ(rfl::json::write(people2), expected1);
    51→  EXPECT_EQ(rfl::json::write(people3), expected2);
    52→}
    53→
    54→}  // namespace test_is_null
