    12→TEST(sqlite, test_full_join) {
    13→  struct Person {
    14→    sqlgen::PrimaryKey<uint32_t> id;
    15→    std::string first_name;
    16→    std::string last_name;
    17→  };
    18→
    19→  struct Pet {
    20→    sqlgen::PrimaryKey<uint32_t> id;
    21→    std::string name;
    22→    uint32_t owner_id;
    23→  };
    24→
    25→  const auto people = std::vector<Person>({
    26→      Person{.id = 1, .first_name = "Homer", .last_name = "Simpson"},
    27→      Person{.id = 2, .first_name = "Marge", .last_name = "Simpson"},
    28→      Person{.id = 3, .first_name = "Bart", .last_name = "Simpson"},
    29→      Person{.id = 4, .first_name = "Lisa", .last_name = "Simpson"},
    30→  });
    31→
    32→  const auto pets = std::vector<Pet>({
    33→      Pet{.id = 1, .name = "Santa's Little Helper", .owner_id = 1},
    34→      Pet{.id = 2, .name = "Snowball", .owner_id = 4},
    35→      Pet{.id = 3, .name = "Mr. Teeny", .owner_id = 99},
    36→  });
    37→
    38→  using namespace sqlgen;
    39→  using namespace sqlgen::literals;
    40→
    41→  struct PersonAndPet {
    42→    std::optional<std::string> first_name;
    43→    std::optional<std::string> last_name;
    44→    std::optional<std::string> pet_name;
    45→  };
    46→
    47→  const auto get_all =
    48→      select_from<Person, "t1">("first_name"_t1 | as<"first_name">,
    49→                                "last_name"_t1 | as<"last_name">,
    50→                                "name"_t2 | as<"pet_name">) |
    51→      full_join<Pet, "t2">("id"_t1 == "owner_id"_t2) |
    52→      order_by("id"_t1, "id"_t2) | to<std::vector<PersonAndPet>>;
    53→
    54→  const auto result = sqlite::connect()
    55→                          .and_then(write(std::ref(people)))
    56→                          .and_then(write(std::ref(pets)))
    57→                          .and_then(get_all)
    58→                          .value();
    59→
    60→  const std::string expected_query =
    61→      R"(SELECT t1."first_name" AS "first_name", t1."last_name" AS "last_name", t2."name" AS "pet_name" FROM "Person" t1 FULL JOIN "Pet" t2 ON t1."id" = t2."owner_id" ORDER BY t1."id", t2."id")";
