   330→}  // namespace transpilation
   331→
   332→template <class TableType, class... FieldTypes>
   333→inline auto select_from(const FieldTypes&... _fields) {
   334→  using FieldsType =
   335→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   336→  return SelectFrom<transpilation::TableWrapper<TableType>, Nothing,
   337→                    FieldsType>{
   338→      .fields_ =
   339→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   340→      .from_ = transpilation::TableWrapper<TableType>{}};
   341→}
   342→
   343→template <class TableType, rfl::internal::StringLiteral _alias,
   344→          class... FieldTypes>
   345→inline auto select_from(const FieldTypes&... _fields) {
   346→  using FieldsType =
   347→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   348→  return SelectFrom<transpilation::TableWrapper<TableType>, Literal<_alias>,
   349→                    FieldsType>{
   350→      .fields_ =
   351→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   352→      .from_ = transpilation::TableWrapper<TableType>{}};
   353→}
   354→
   355→template <rfl::internal::StringLiteral _alias, class QueryType,
   356→          class... FieldTypes>
   357→inline auto select_from(const QueryType& _query, const FieldTypes&... _fields) {
   358→  using FieldsType =
   359→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   360→  return SelectFrom<QueryType, Literal<_alias>, FieldsType>{
   361→      .fields_ =
   362→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   363→      .from_ = _query};
   364→}
