    38→  using namespace sqlgen;
    39→  using namespace sqlgen::literals;
    40→
    41→  struct PersonWithPet {
    42→    std::string first_name;
    43→    std::string last_name;
    44→    std::optional<std::string> pet_name;
    45→  };
    46→
    47→  const auto get_people_with_pets =
