    51→template <rfl::internal::StringLiteral _name, class ValueType, class WhereType,
    52→          class... ColTypes>
    53→struct ToSQL<CreateIndex<_name, ValueType, WhereType, ColTypes...>> {
    54→  dynamic::Statement operator()(const auto& _create_index) const {
    55→    return transpilation::to_create_index<
    56→        ValueType, columns_t<ValueType, typename ColTypes::ColType...>,
    57→        WhereType>(_name.str(), _create_index.unique_,
    58→                   _create_index.if_not_exists_, _create_index.where_);
    59→  }
    60→};
    61→
    62→template <class T>
    63→struct ToSQL<CreateTable<T>> {
    64→  dynamic::Statement operator()(const auto&) const {
    65→    return to_create_table<T>();
    66→  }
    67→};
    68→
    69→template <class T, class WhereType>
    70→struct ToSQL<DeleteFrom<T, WhereType>> {
    71→  dynamic::Statement operator()(const auto& _delete_from) const {
    72→    return to_delete_from<T>(_delete_from.where_);
    73→  }
    74→};
    75→
    76→template <class T>
    77→struct ToSQL<Drop<T>> {
    78→  dynamic::Statement operator()(const auto& _drop) const {
    79→    return to_drop<T>(_drop.what_, _drop.if_exists_, _drop.cascade_);
    80→  }
    81→};
