   103→    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, WhereType,
   104→               GroupByType, OrderByType, LimitType, ToType>> {
   105→  dynamic::Statement operator()(const auto& _select_from) const {
   106→    using TableTupleType =
   107→        table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   108→    return to_select_from<TableTupleType, AliasType, FieldsType,
   109→                          TableOrQueryType, JoinsType, WhereType, GroupByType,
   110→                          OrderByType, LimitType>(
   111→        _select_from.fields_, _select_from.from_, _select_from.joins_,
   112→        _select_from.where_, _select_from.limit_);
   113→  }
   114→};
   115→
