     1→#ifndef SQLGEN_PRIMARY_KEY_HPP_
     2→#define SQLGEN_PRIMARY_KEY_HPP_
     3→
     4→#include <type_traits>
     5→
     6→#include "transpilation/is_nullable.hpp"
     7→
     8→namespace sqlgen {
     9→
    10→inline constexpr bool auto_incr = true;
    11→
    12→template <class T, bool _auto_incr = false>
    13→struct PrimaryKey {
    14→  using ReflectionType = T;
    15→  static constexpr bool auto_incr = _auto_incr;
    16→
    17→  static_assert(
    18→      !transpilation::is_nullable_v<T>,
    19→      "A primary key cannot be nullable. Please use a non-nullable type.");
    20→  static_assert(!_auto_incr || std::is_integral_v<T>,
    21→                "The type of an auto-incrementing primary key must be "
    22→                "integral. Please use an integral type or remove auto_incr.");
    23→
    24→  PrimaryKey() : value_(T()) {}
    25→
    26→  PrimaryKey(const T& _value) : value_(_value) {}
    27→
    28→  PrimaryKey(PrimaryKey&& _other) noexcept = default;
    29→
    30→  PrimaryKey(const PrimaryKey& _other) = default;
    31→
    32→  template <class U, bool _other_auto_incr>
    33→  PrimaryKey(const PrimaryKey<U, _other_auto_incr>& _other)
    34→      : value_(_other.get()) {}
    35→
    36→  template <class U, bool _other_auto_incr>
    37→  PrimaryKey(PrimaryKey<U, _other_auto_incr>&& _other) : value_(_other.get()) {}
    38→
    39→  template <class U,
    40→            typename std::enable_if<std::is_convertible_v<U, ReflectionType>,
    41→                                    bool>::type = true>
    42→  PrimaryKey(const U& _value) : value_(_value) {}
    43→
    44→  template <class U,
    45→            typename std::enable_if<std::is_convertible_v<U, ReflectionType>,
    46→                                    bool>::type = true>
    47→  PrimaryKey(U&& _value) noexcept : value_(std::forward<U>(_value)) {}
    48→
    49→  template <class U,
    50→            typename std::enable_if<std::is_convertible_v<U, ReflectionType>,
    51→                                    bool>::type = true>
    52→  PrimaryKey(const PrimaryKey<U>& _other) : value_(_other.value()) {}
    53→
    54→  ~PrimaryKey() = default;
    55→
    56→  /// Returns the underlying object.
    57→  ReflectionType& get() { return value_; }
    58→
    59→  /// Returns the underlying object.
    60→  const ReflectionType& get() const { return value_; }
    61→
    62→  /// Returns the underlying object.
    63→  ReflectionType& operator()() { return value_; }
    64→
    65→  /// Returns the underlying object.
    66→  const ReflectionType& operator()() const { return value_; }
    67→
    68→  /// Assigns the underlying object.
    69→  auto& operator=(const ReflectionType& _value) {
    70→    value_ = _value;
    71→    return *this;
    72→  }
    73→
    74→  /// Assigns the underlying object.
    75→  template <class U,
    76→            typename std::enable_if<std::is_convertible_v<U, ReflectionType>,
    77→                                    bool>::type = true>
    78→  auto& operator=(const U& _value) {
    79→    value_ = _value;
    80→    return *this;
    81→  }
    82→
    83→  /// Assigns the underlying object.
    84→  PrimaryKey& operator=(const PrimaryKey& _other) = default;
    85→
    86→  /// Assigns the underlying object.
    87→  PrimaryKey& operator=(PrimaryKey&& _other) = default;
    88→
    89→  /// Assigns the underlying object.
    90→  template <class U, bool _other_auto_incr>
    91→  auto& operator=(const PrimaryKey<U, _other_auto_incr>& _other) {
    92→    value_ = _other.get();
    93→    return *this;
    94→  }
    95→
    96→  /// Assigns the underlying object.
    97→  template <class U, bool _other_auto_incr>
    98→  auto& operator=(PrimaryKey<U, _other_auto_incr>&& _other) {
    99→    value_ = std::move(_other.value_);
   100→    return *this;
   101→  }
   102→
   103→  /// Necessary for the automated transpilation to work.
   104→  const T& reflection() const { return value_; }
   105→
   106→  /// Assigns the underlying object.
   107→  void set(const T& _value) { value_ = _value; }
   108→
   109→  /// Returns the underlying object.
   110→  T& value() { return value_; }
   111→
   112→  /// Returns the underlying object.
   113→  const T& value() const { return value_; }
   114→
   115→  /// The underlying value.
   116→  T value_;
   117→};
   118→
   119→}  // namespace sqlgen
   120→
   121→#endif
