    35→      std::vector<Relationship>({Relationship{.parent_id = 0, .child_id = 2},
    36→                                 Relationship{.parent_id = 0, .child_id = 3},
    37→                                 Relationship{.parent_id = 0, .child_id = 4},
    38→                                 Relationship{.parent_id = 1, .child_id = 2},
