    68→std::string aggregation_to_sql(
    69→    const dynamic::Aggregation& _aggregation) noexcept {
    70→  return _aggregation.val.visit([](const auto& _agg) -> std::string {
    71→    using Type = std::remove_cvref_t<decltype(_agg)>;
    72→    std::stringstream stream;
    73→    if constexpr (std::is_same_v<Type, dynamic::Aggregation::Avg>) {
    74→      stream << "AVG(" << operation_to_sql(*_agg.val) << ")";
    75→
    76→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Count>) {
    77→      const auto val =
    78→          std::string(_agg.val && _agg.distinct ? "DISTINCT " : "") +
    79→          (_agg.val ? column_or_value_to_sql(*_agg.val) : std::string("*"));
    80→      stream << "COUNT(" << val << ")";
    81→
    82→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Max>) {
    83→      stream << "MAX(" << operation_to_sql(*_agg.val) << ")";
    84→
    85→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Min>) {
    86→      stream << "MIN(" << operation_to_sql(*_agg.val) << ")";
    87→
    88→    } else if constexpr (std::is_same_v<Type, dynamic::Aggregation::Sum>) {
    89→      stream << "SUM(" << operation_to_sql(*_agg.val) << ")";
    90→
    91→    } else {
    92→      static_assert(rfl::always_false_v<Type>, "Not all cases were covered.");
    93→    }
    94→    return stream.str();
    95→  });
    96→}
