   169→
   170→template <class ConditionType>
   171→std::string condition_to_sql_impl(const ConditionType& _condition) noexcept {
   172→  using namespace std::ranges::views;
   173→
   174→  using C = std::remove_cvref_t<ConditionType>;
   175→
   176→  std::stringstream stream;
   177→
   178→  if constexpr (std::is_same_v<C, dynamic::Condition::And>) {
   179→    stream << "(" << condition_to_sql(*_condition.cond1) << ") AND ("
   180→           << condition_to_sql(*_condition.cond2) << ")";
   181→
   182→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Equal>) {
   183→    stream << operation_to_sql(_condition.op1) << " = "
   184→           << operation_to_sql(_condition.op2);
   185→
   186→  } else if constexpr (std::is_same_v<C, dynamic::Condition::GreaterEqual>) {
   187→    stream << operation_to_sql(_condition.op1)
   188→           << " >= " << operation_to_sql(_condition.op2);
   189→
   190→  } else if constexpr (std::is_same_v<C, dynamic::Condition::GreaterThan>) {
   191→    stream << operation_to_sql(_condition.op1) << " > "
   192→           << operation_to_sql(_condition.op2);
   193→
   194→  } else if constexpr (std::is_same_v<C, dynamic::Condition::In>) {
   195→    stream << operation_to_sql(_condition.op) << " IN ("
   196→           << internal::strings::join(
   197→                  ", ",
   198→                  internal::collect::vector(_condition.patterns |
   199→                                            transform(column_or_value_to_sql)))
   200→           << ")";
   201→
   202→  } else if constexpr (std::is_same_v<C, dynamic::Condition::IsNull>) {
   203→    stream << operation_to_sql(_condition.op) << " IS NULL";
   204→
   205→  } else if constexpr (std::is_same_v<C, dynamic::Condition::IsNotNull>) {
   206→    stream << operation_to_sql(_condition.op) << " IS NOT NULL";
   207→
   208→  } else if constexpr (std::is_same_v<C, dynamic::Condition::LesserEqual>) {
   209→    stream << operation_to_sql(_condition.op1)
   210→           << " <= " << operation_to_sql(_condition.op2);
   211→
   212→  } else if constexpr (std::is_same_v<C, dynamic::Condition::LesserThan>) {
   213→    stream << operation_to_sql(_condition.op1) << " < "
   214→           << operation_to_sql(_condition.op2);
   215→
   216→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Like>) {
   217→    stream << operation_to_sql(_condition.op) << " LIKE "
   218→           << column_or_value_to_sql(_condition.pattern);
   219→
   220→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Not>) {
   221→    stream << "NOT (" << condition_to_sql(*_condition.cond) << ")";
   222→
   223→  } else if constexpr (std::is_same_v<C, dynamic::Condition::NotEqual>) {
   224→    stream << operation_to_sql(_condition.op1)
   225→           << " != " << operation_to_sql(_condition.op2);
   226→
   227→  } else if constexpr (std::is_same_v<C, dynamic::Condition::NotLike>) {
   228→    stream << operation_to_sql(_condition.op) << " NOT LIKE "
   229→           << column_or_value_to_sql(_condition.pattern);
   230→
   231→  } else if constexpr (std::is_same_v<C, dynamic::Condition::NotIn>) {
   232→    stream << operation_to_sql(_condition.op) << " NOT IN ("
   233→           << internal::strings::join(
   234→                  ", ",
   235→                  internal::collect::vector(_condition.patterns |
   236→                                            transform(column_or_value_to_sql)))
   237→           << ")";
   238→
   239→  } else if constexpr (std::is_same_v<C, dynamic::Condition::Or>) {
   240→    stream << "(" << condition_to_sql(*_condition.cond1) << ") OR ("
   241→           << condition_to_sql(*_condition.cond2) << ")";
   242→
   243→  } else {
   244→    static_assert(rfl::always_false_v<C>, "Not all cases were covered.");
   245→  }
   246→  return stream.str();
   247→}
