   613→
   614→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Trim>) {
   615→      stream << "trim(" << operation_to_sql(*_s.op1) << ", "
   616→             << operation_to_sql(*_s.op2) << ")";
   617→
   618→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Unixepoch>) {
   619→      stream << "unixepoch(" << operation_to_sql(*_s.op1) << ", 'subsec')";
   620→
   621→    } else if constexpr (std::is_same_v<Type, dynamic::Operation::Upper>) {
