   213→  template <class... ColTypes>
   214→  friend auto operator|(const SelectFrom& _s, const GroupBy<ColTypes...>&) {
   215→    static_assert(
   216→        std::is_same_v<GroupByType, Nothing>,
   217→        "You cannot call group_by(...) twice (but you can group by more "
   218→        "than one column).");
   219→    static_assert(std::is_same_v<OrderByType, Nothing>,
   220→                  "You cannot call order_by(...) before group_by(...).");
   221→    static_assert(std::is_same_v<LimitType, Nothing>,
   222→                  "You cannot call limit(...) before group_by(...).");
   223→    static_assert(std::is_same_v<ToType, Nothing>,
   224→                  "You cannot call to<...> before group_by(...).");
   225→    static_assert(sizeof...(ColTypes) != 0,
   226→                  "You must assign at least one column to group_by.");
   227→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   228→                      WhereType,
   229→                      transpilation::group_by_t<TableOrQueryType,
   230→                                                typename ColTypes::ColType...>,
   231→                      OrderByType, LimitType, ToType>{.fields_ = _s.fields_,
   232→                                                      .from_ = _s.from_,
   233→                                                      .joins_ = _s.joins_,
   234→                                                      .where_ = _s.where_};
   235→  }
   236→
   237→  template <class... ColTypes>
   238→  friend auto operator|(const SelectFrom& _s, const OrderBy<ColTypes...>&) {
   239→    static_assert(
   240→        std::is_same_v<OrderByType, Nothing>,
   241→        "You cannot call order_by(...) twice (but you can order by more "
   242→        "than one column).");
   243→    static_assert(std::is_same_v<LimitType, Nothing>,
   244→                  "You cannot call limit(...) before order_by(...).");
   245→    static_assert(std::is_same_v<ToType, Nothing>,
   246→                  "You cannot call to<...> before order_by(...).");
   247→    static_assert(sizeof...(ColTypes) != 0,
   248→                  "You must assign at least one column to order_by.");
   249→
   250→    using TableTupleType =
   251→        transpilation::table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   252→
   253→    using NewOrderByType = transpilation::order_by_t<
   254→        TableTupleType, GroupByType,
   255→        typename std::remove_cvref_t<ColTypes>::ColType...>;
   256→
   257→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   258→                      WhereType, GroupByType, NewOrderByType, LimitType,
   259→                      ToType>{.fields_ = _s.fields_,
   260→                              .from_ = _s.from_,
   261→                              .joins_ = _s.joins_,
   262→                              .where_ = _s.where_};
   263→  }
   264→
   265→  friend auto operator|(const SelectFrom& _s, const Limit& _limit) {
   266→    static_assert(std::is_same_v<LimitType, Nothing>,
   267→                  "You cannot call limit twice.");
   268→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   269→                      WhereType, GroupByType, OrderByType, Limit, ToType>{
   270→        .fields_ = _s.fields_,
   271→        .from_ = _s.from_,
   272→        .joins_ = _s.joins_,
   273→        .where_ = _s.where_,
   274→        .limit_ = _limit};
   275→  }
   276→
   277→  template <class NewToType>
   278→  friend auto operator|(const SelectFrom& _s, const To<NewToType>&) {
   279→    static_assert(std::is_same_v<ToType, Nothing>,
   280→                  "You cannot call to<...> twice.");
   281→    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
   282→                      WhereType, GroupByType, OrderByType, LimitType,
   283→                      NewToType>{.fields_ = _s.fields_,
   284→                                 .from_ = _s.from_,
   285→                                 .joins_ = _s.joins_,
   286→                                 .where_ = _s.where_,
   287→                                 .limit_ = _s.limit_};
   288→  }
   289→
   290→  FieldsType fields_;
   291→
   292→  TableOrQueryType from_;
   293→
   294→  JoinsType joins_;
   295→
   296→  WhereType where_;
   297→
   298→  LimitType limit_;
   299→};
   300→
   301→namespace transpilation {
   302→
   303→template <class TableOrQueryType, class AliasType, class FieldsType,
   304→          class JoinsType, class... Args>
   305→struct ExtractTable<
   306→    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, Args...>,
   307→    false> {
   308→  using TableTupleType = table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   309→  using Type = fields_to_named_tuple_t<TableTupleType, FieldsType>;
   310→};
   311→
   312→template <class TableOrQueryType, class AliasType, class FieldsType,
   313→          class JoinsType, class WhereType, class GroupByType,
   314→          class OrderByType, class LimitType, class ToType>
   315→struct ToTableOrQuery<
   316→    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, WhereType,
   317→               GroupByType, OrderByType, LimitType, ToType>> {
   318→  dynamic::SelectFrom::TableOrQueryType operator()(const auto& _query) {
   319→    using TableTupleType =
   320→        table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   321→    return Ref<dynamic::SelectFrom>::make(
   322→        transpilation::to_select_from<TableTupleType, AliasType, FieldsType,
   323→                                      TableOrQueryType, JoinsType, WhereType,
   324→                                      GroupByType, OrderByType, LimitType>(
   325→            _query.fields_, _query.from_, _query.joins_, _query.where_,
   326→            _query.limit_));
   327→  }
   328→};
   329→
   330→}  // namespace transpilation
   331→
   332→template <class TableType, class... FieldTypes>
   333→inline auto select_from(const FieldTypes&... _fields) {
   334→  using FieldsType =
   335→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   336→  return SelectFrom<transpilation::TableWrapper<TableType>, Nothing,
   337→                    FieldsType>{
   338→      .fields_ =
   339→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   340→      .from_ = transpilation::TableWrapper<TableType>{}};
   341→}
   342→
   343→template <class TableType, rfl::internal::StringLiteral _alias,
   344→          class... FieldTypes>
   345→inline auto select_from(const FieldTypes&... _fields) {
   346→  using FieldsType =
   347→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   348→  return SelectFrom<transpilation::TableWrapper<TableType>, Literal<_alias>,
   349→                    FieldsType>{
   350→      .fields_ =
   351→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   352→      .from_ = transpilation::TableWrapper<TableType>{}};
   353→}
   354→
   355→template <rfl::internal::StringLiteral _alias, class QueryType,
   356→          class... FieldTypes>
   357→inline auto select_from(const QueryType& _query, const FieldTypes&... _fields) {
   358→  using FieldsType =
   359→      rfl::Tuple<typename internal::GetColType<FieldTypes>::Type...>;
   360→  return SelectFrom<QueryType, Literal<_alias>, FieldsType>{
   361→      .fields_ =
   362→          FieldsType(internal::GetColType<FieldTypes>::get_value(_fields)...),
   363→      .from_ = _query};
   364→}
   365→
   366→}  // namespace sqlgen
   367→
   368→#endif
