    33→      {Person{
    34→           .id = 0, .first_name = "Homer", .last_name = "Simpson", .age = 45},
    35→       Person{
    36→           .id = 1, .first_name = "Marge", .last_name = "Simpson", .age = 40},
    37→       Person{.id = 2, .first_name = "Bart", .last_name = "Simpson", .age = 10},
    38→       Person{.id = 3, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
    39→       Person{
    40→           .id = 4, .first_name = "Maggie", .last_name = "Simpson", .age = 0}});
    41→
    42→  const auto names_query = select_from<Person>("first_name"_c, "last_name"_c);
    43→
    44→  const auto get_names = create_as<Name>(names_query) | if_not_exists;
    45→
    46→  const auto names = sqlite::connect()
    47→                         .and_then(drop<Name> | if_exists)
    48→                         .and_then(drop<Person> | if_exists)
    49→                         .and_then(write(std::ref(people)))
