    53→
    54→  } else {
    55→    const auto to_container = [](auto range) -> Result<ContainerType> {
    56→      using ValueType = transpilation::value_t<ContainerType>;
    57→      ContainerType container;
    58→      for (auto& res : range) {
    59→        if (res) {
    60→          if constexpr (std::is_class_v<ValueType>) {
    61→            container.emplace_back(
    62→                rfl::from_named_tuple<ValueType>(std::move(*res)));
    63→          } else {
    64→            auto vals = (*res).values();
    65→            container.emplace_back(static_cast<ValueType>(rfl::get<0>(vals)));
