    98→std::string pad_with_zeros(const std::string& _str,
    99→                           const size_t _expected_length) {
   100→  if (_str.size() < _expected_length) {
   101→    return std::string(_expected_length - _str.size(), '0') + _str;
   102→  } else {
   103→    return _str;
   104→  }
   105→}
