   107→std::string column_or_value_to_sql(
   108→    const dynamic::ColumnOrValue& _col) noexcept {
   109→  const auto handle_value = [](const auto& _v) -> std::string {
   110→    using Type = std::remove_cvref_t<decltype(_v)>;
   111→    if constexpr (std::is_same_v<Type, dynamic::String>) {
   112→      return "'" + escape_single_quote(_v.val) + "'";
   113→
   114→    } else if constexpr (std::is_same_v<Type, dynamic::Duration>) {
   115→      const auto prefix = std::string("'") + (_v.val >= 0 ? "+" : "-");
   116→      const auto val = std::abs(_v.val);
   117→      switch (_v.unit) {
   118→        case dynamic::TimeUnit::milliseconds: {
   119→          const auto h = (val / 3600000);
   120→          const auto m = (val / 60000) % 60;
   121→          const auto s = (val / 1000) % 60;
   122→          const auto ms = val % 1000;
   123→          return prefix + pad_with_zeros(std::to_string(h), 2) + ":" +
   124→                 pad_with_zeros(std::to_string(m), 2) + ":" +
   125→                 pad_with_zeros(std::to_string(s), 2) + "." +
   126→                 pad_with_zeros(std::to_string(ms), 3) + "'";
   127→        }
   128→
   129→        case dynamic::TimeUnit::weeks:
   130→          return prefix + std::to_string(val * 7) + " days'";
   131→
   132→        default:
   133→          return prefix + std::to_string(val) + " " +
   134→                 rfl::enum_to_string(_v.unit) + "'";
   135→      }
   136→
   137→    } else if constexpr (std::is_same_v<Type, dynamic::Timestamp>) {
   138→      return std::to_string(_v.seconds_since_unix);
   139→
   140→    } else {
   141→      return std::to_string(_v.val);
   142→    }
   143→  };
   144→
   145→  return _col.visit([&](const auto& _c) -> std::string {
   146→    using Type = std::remove_cvref_t<decltype(_c)>;
   147→    if constexpr (std::is_same_v<Type, dynamic::Column>) {
   148→      if (_c.alias) {
   149→        return *_c.alias + "." + wrap_in_quotes(_c.name);
   150→      } else {
   151→        return wrap_in_quotes(_c.name);
   152→      }
   153→    } else {
   154→      return _c.val.visit(handle_value);
   155→    }
   156→  });
   157→}
