   397→template <class InsertOrWrite>
   398→std::string insert_or_write_to_sql(const InsertOrWrite& _stmt) noexcept {
   399→  using namespace std::ranges::views;
   400→
   401→  const auto in_quotes = [](const std::string& _str) -> std::string {
   402→    return "\"" + _str + "\"";
