   409→  const auto as_excluded = [](const std::string& _str) -> std::string {
   410→    return _str + "=excluded." + _str;
   411→  };
   412→
   413→  std::stringstream stream;
   414→  stream << "INSERT INTO ";
   415→
   416→  if (_stmt.table.schema) {
   417→    stream << wrap_in_quotes(*_stmt.table.schema) << ".";
   418→  }
   419→  stream << wrap_in_quotes(_stmt.table.name);
   420→
   421→  stream << " (";
   422→  stream << internal::strings::join(
   423→      ", ", internal::collect::vector(_stmt.columns | transform(in_quotes)));
   424→  stream << ")";
   425→
   426→  stream << " VALUES (";
   427→  stream << internal::strings::join(
   428→      ", ",
   429→      internal::collect::vector(_stmt.columns | transform(to_questionmark)));
