   642→std::string properties_to_sql(const dynamic::types::Properties& _p) noexcept {
   643→  return [&]() -> std::string {
   644→    return std::string(_p.primary ? " PRIMARY KEY" : "") +
   645→           std::string(_p.auto_incr ? " AUTOINCREMENT" : "") +
   646→           std::string(_p.nullable ? "" : " NOT NULL") +
   647→           std::string(_p.unique ? " UNIQUE" : "");
   648→  }() + [&]() -> std::string {
   649→    if (!_p.foreign_key_reference) {
   650→      return "";
   651→    }
   652→    const auto& ref = *_p.foreign_key_reference;
   653→    return " REFERENCES " + wrap_in_quotes(ref.table) + "(" +
   654→           wrap_in_quotes(ref.column) + ")";
   655→  }();
   656→}
   657→
   658→std::string select_from_to_sql(const dynamic::SelectFrom& _stmt) noexcept {
   659→  using namespace std::ranges::views;
   660→
   661→  const auto order_by_to_str = [](const auto& _w) -> std::string {
   662→    return column_or_value_to_sql(_w.column) + (_w.desc ? " DESC" : "");
   663→  };
   664→
   665→  std::stringstream stream;
   666→
   667→  stream << "SELECT ";
   668→  stream << internal::strings::join(
   669→      ", ", internal::collect::vector(_stmt.fields | transform(field_to_str)));
   670→
   671→  stream << " FROM " << table_or_query_to_sql(_stmt.table_or_query);
   672→
   673→  if (_stmt.alias) {
   674→    stream << " " << *_stmt.alias;
   675→  }
   676→
   677→  if (_stmt.joins) {
   678→    stream << " "
   679→           << internal::strings::join(
   680→                  " ", internal::collect::vector(*_stmt.joins |
   681→                                                 transform(join_to_sql)));
   682→  }
   683→
   684→  if (_stmt.where) {
   685→    stream << " WHERE " << condition_to_sql(*_stmt.where);
   686→  }
   687→
   688→  if (_stmt.group_by) {
   689→    stream << " GROUP BY "
   690→           << internal::strings::join(
   691→                  ", ",
   692→                  internal::collect::vector(_stmt.group_by->columns |
   693→                                            transform(column_or_value_to_sql)));
   694→  }
   695→
   696→  if (_stmt.order_by) {
   697→    stream << " ORDER BY "
   698→           << internal::strings::join(
   699→                  ", ", internal::collect::vector(_stmt.order_by->columns |
   700→                                                  transform(order_by_to_str)));
   701→  }
   702→
   703→  if (_stmt.limit) {
   704→    stream << " LIMIT " << _stmt.limit->val;
   705→  }
   706→
   707→  return stream.str();
   708→}
   709→
   710→std::string table_or_query_to_sql(
   711→    const dynamic::SelectFrom::TableOrQueryType& _table_or_query) noexcept {
   712→  return _table_or_query.visit([](const auto& _t) -> std::string {
   713→    using Type = std::remove_cvref_t<decltype(_t)>;
   714→    if constexpr (std::is_same_v<Type, dynamic::Table>) {
   715→      return wrap_in_quotes(_t.name);
   716→    } else {
   717→      return "(" + select_from_to_sql(*_t) + ")";
   718→    }
   719→  });
   720→}
   721→
   722→std::string to_sql_impl(const dynamic::Statement& _stmt) noexcept {
   723→  return _stmt.visit([&](const auto& _s) -> std::string {
   724→    using S = std::remove_cvref_t<decltype(_s)>;
   725→    if constexpr (std::is_same_v<S, dynamic::CreateIndex>) {
   726→      return create_index_to_sql(_s);
   727→
   728→    } else if constexpr (std::is_same_v<S, dynamic::CreateTable>) {
   729→      return create_table_to_sql(_s);
   730→
   731→    } else if constexpr (std::is_same_v<S, dynamic::CreateAs>) {
   732→      return create_as_to_sql(_s);
   733→
   734→    } else if constexpr (std::is_same_v<S, dynamic::DeleteFrom>) {
   735→      return delete_from_to_sql(_s);
   736→
   737→    } else if constexpr (std::is_same_v<S, dynamic::Drop>) {
   738→      return drop_to_sql(_s);
   739→
   740→    } else if constexpr (std::is_same_v<S, dynamic::Insert>) {
   741→      return insert_or_write_to_sql(_s);
   742→
   743→    } else if constexpr (std::is_same_v<S, dynamic::SelectFrom>) {
   744→      return select_from_to_sql(_s);
   745→
   746→    } else if constexpr (std::is_same_v<S, dynamic::Update>) {
   747→      return update_to_sql(_s);
   748→
   749→    } else if constexpr (std::is_same_v<S, dynamic::Write>) {
   750→      return insert_or_write_to_sql(_s);
   751→
   752→    } else {
   753→      static_assert(rfl::always_false_v<S>, "Unsupported type.");
   754→    }
   755→  });
   756→}
   757→
   758→std::string type_to_sql(const dynamic::Type& _type) noexcept {
   759→  return _type.visit([](const auto _t) -> std::string {
   760→    using T = std::remove_cvref_t<decltype(_t)>;
   761→
   762→    if constexpr (std::is_same_v<T, dynamic::types::Boolean> ||
   763→                  std::is_same_v<T, dynamic::types::Int8> ||
   764→                  std::is_same_v<T, dynamic::types::Int16> ||
   765→                  std::is_same_v<T, dynamic::types::Int32> ||
   766→                  std::is_same_v<T, dynamic::types::Int64> ||
   767→                  std::is_same_v<T, dynamic::types::UInt8> ||
   768→                  std::is_same_v<T, dynamic::types::UInt16> ||
   769→                  std::is_same_v<T, dynamic::types::UInt32> ||
   770→                  std::is_same_v<T, dynamic::types::UInt64>) {
   771→      return "INTEGER";
   772→
   773→    } else if constexpr (std::is_same_v<T, dynamic::types::Float32> ||
   774→                         std::is_same_v<T, dynamic::types::Float64>) {
   775→      return "REAL";
   776→
   777→    } else if constexpr (std::is_same_v<T, dynamic::types::Unknown> ||
   778→                         std::is_same_v<T, dynamic::types::Text> ||
   779→                         std::is_same_v<T, dynamic::types::VarChar> ||
   780→                         std::is_same_v<T, dynamic::types::Date> ||
   781→                         std::is_same_v<T, dynamic::types::Timestamp> ||
   782→                         std::is_same_v<T, dynamic::types::TimestampWithTZ>) {
   783→      return "TEXT";
   784→
   785→    } else if constexpr (std::is_same_v<T, dynamic::types::JSON>) {
   786→      return "JSONB";
   787→
   788→    } else if constexpr (std::is_same_v<T, dynamic::types::Dynamic>) {
   789→      return _t.type_name;
   790→    } else if constexpr (std::is_same_v<T, dynamic::types::Enum>) {
   791→      return "TEXT";
   792→    } else {
   793→      static_assert(rfl::always_false_v<T>, "Not all cases were covered.");
   794→    }
   795→  });
   796→}
   797→
   798→std::string update_to_sql(const dynamic::Update& _stmt) noexcept {
   799→  using namespace std::ranges::views;
   800→
   801→  const auto to_str = [](const auto& _set) -> std::string {
   802→    return "\"" + _set.col.name + "\" = " + column_or_value_to_sql(_set.to);
   803→  };
   804→
   805→  std::stringstream stream;
   806→
   807→  stream << "UPDATE ";
   808→
   809→  if (_stmt.table.schema) {
   810→    stream << "\"" << *_stmt.table.schema << "\".";
   811→  }
   812→  stream << "\"" << _stmt.table.name << "\"";
   813→
   814→  stream << " SET ";
   815→
   816→  stream << internal::strings::join(
   817→      ", ", internal::collect::vector(_stmt.sets | transform(to_str)));
   818→
   819→  if (_stmt.where) {
   820→    stream << " WHERE " << condition_to_sql(*_stmt.where);
   821→  }
   822→
   823→  stream << ";";
   824→
   825→  return stream.str();
   826→}
