     1→#ifndef SQLGEN_CONNECTIONPOOL_HPP_
     2→#define SQLGEN_CONNECTIONPOOL_HPP_
     3→
     4→#include <atomic>
     5→#include <chrono>
     6→#include <memory>
     7→#include <numeric>
     8→#include <thread>
     9→#include <utility>
    10→#include <vector>
    11→
    12→#include "Ref.hpp"
    13→#include "Result.hpp"
    14→#include "Session.hpp"
    15→
    16→namespace sqlgen {
    17→
    18→struct ConnectionPoolConfig {
    19→  size_t size = 4;
    20→  size_t num_attempts = 10;
    21→  size_t wait_time_in_seconds = 1;
    22→};
    23→
    24→template <class Connection>
    25→class ConnectionPool {
    26→  using ConnPtr = Ref<Connection>;
    27→
    28→ public:
    29→  template <class... Args>
    30→  ConnectionPool(const ConnectionPoolConfig& _config, const Args&... _args) {
    31→    conns_->reserve(_config.size);
    32→    for (size_t i = 0; i < _config.size; ++i) {
    33→      auto conn = Ref<Connection>::make(_args...);
    34→      auto flag = Ref<std::atomic_flag>::make();
    35→      flag->clear();
    36→      conns_->emplace_back(std::make_pair(std::move(conn), std::move(flag)));
    37→    }
    38→  }
    39→
    40→  template <class... Args>
    41→  static Result<ConnectionPool> make(const ConnectionPoolConfig& _config,
    42→                                     const Args&... _args) noexcept {
    43→    try {
    44→      return ConnectionPool(_config, _args...);
    45→    } catch (std::exception& e) {
    46→      return error(e.what());
    47→    }
    48→  }
    49→
    50→  ~ConnectionPool() = default;
    51→
    52→  /// Acquire a session from the pool. Returns an error if no connections are
    53→  /// available after several attempts.
    54→  Result<Ref<Session<Connection>>> acquire() noexcept {
    55→    for (size_t att = 0; att < config_.num_attempts; ++att) {
    56→      if (att != 0) {
    57→        std::this_thread::sleep_for(
    58→            std::chrono::seconds(config_.wait_time_in_seconds));
    59→      }
    60→      for (auto& [conn, flag] : *conns_) {
    61→        if (!flag->test_and_set()) {
    62→          return Ref<Session<Connection>>::make(conn, flag);
    63→        }
    64→      }
    65→    }
    66→    return error("No available connections in the pool.");
    67→  }
    68→
    69→  /// Get the current number of available connections
    70→  size_t available() const {
    71→    return std::accumulate(conns_->begin(), conns_->end(), 0,
    72→                           [](const auto _count, const auto& _p) {
    73→                             return _p.second->test() ? _count : _count + 1;
    74→                           });
    75→  }
    76→
    77→  /// Get the total number of connections in the pool
    78→  size_t size() const { return conns_->size(); }
    79→
    80→ private:
    81→  /// The configuration for the connection pool.
    82→  ConnectionPoolConfig config_;
    83→
    84→  /// The underlying connection objects.
    85→  Ref<std::vector<std::pair<ConnPtr, Ref<std::atomic_flag>>>> conns_;
    86→};
    87→
    88→template <class Connection, class... Args>
    89→Result<ConnectionPool<Connection>> make_connection_pool(
    90→    const ConnectionPoolConfig& _config, const Args&... _args) noexcept {
    91→  return ConnectionPool<Connection>::make(_config, _args...);
    92→}
    93→
    94→template <class Connection>
    95→Result<Ref<Session<Connection>>> session(
    96→    ConnectionPool<Connection> _pool) noexcept {
    97→  return _pool.acquire();
    98→}
    99→
   100→template <class Connection>
   101→Result<Ref<Session<Connection>>> session(
   102→    Result<ConnectionPool<Connection>> _res) noexcept {
   103→  return _res.and_then([](auto _pool) { return session(_pool); });
   104→}
   105→
   106→}  // namespace sqlgen
   107→
   108→#endif
