   311→
   312→template <class TableOrQueryType, class AliasType, class FieldsType,
   313→          class JoinsType, class WhereType, class GroupByType,
   314→          class OrderByType, class LimitType, class ToType>
   315→struct ToTableOrQuery<
   316→    SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType, WhereType,
   317→               GroupByType, OrderByType, LimitType, ToType>> {
   318→  dynamic::SelectFrom::TableOrQueryType operator()(const auto& _query) {
   319→    using TableTupleType =
   320→        table_tuple_t<TableOrQueryType, AliasType, JoinsType>;
   321→    return Ref<dynamic::SelectFrom>::make(
   322→        transpilation::to_select_from<TableTupleType, AliasType, FieldsType,
   323→                                      TableOrQueryType, JoinsType, WhereType,
   324→                                      GroupByType, OrderByType, LimitType>(
   325→            _query.fields_, _query.from_, _query.joins_, _query.where_,
   326→            _query.limit_));
   327→  }
   328→};
